a:1:{s:37:"../../../app/Events/RealtimeEvent.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:24:"App\Events\RealtimeEvent";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:1393:"/**
 * Base for every MyVivahAI realtime chat event (Phase 3E).
 *
 * Behaviour guarantees:
 *   - ShouldBroadcastNow   — dispatched INLINE (no queue worker required), right
 *                            after the REST request that caused it commits.
 *   - Commit ordering      — every call site (ChatMessageService,
 *                            ChatConversationService, PresenceService) fires via
 *                            RealtimeBroadcaster AFTER its own DB transaction
 *                            has closed, so MySQL (source of truth) always holds
 *                            the row BEFORE any broadcast. No queue worker, no
 *                            transaction-manager indirection.
 *   - ShouldRescue         — a dead/unreachable realtime transport throws a
 *                            BroadcastException that is swallowed + logged; the
 *                            REST request never fails because of realtime.
 *   - broadcastWhen        — global kill-switch shared by every event
 *                            (config('chat.realtime.enabled')), so a fully
 *                            REST-only deployment dispatches nothing at all.
 *
 * Payload rule (AGENTS.md §15 / security.md): events carry ONLY public ids and
 * minimal display data — never API secrets, PASETO tokens, private keys,
 * internal primary keys, full profiles or audit material.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:10:"App\Events";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:5:{s:20:"interactswithsockets";s:44:"Illuminate\Broadcasting\InteractsWithSockets";s:18:"shouldbroadcastnow";s:52:"Illuminate\Contracts\Broadcasting\ShouldBroadcastNow";s:12:"shouldrescue";s:46:"Illuminate\Contracts\Broadcasting\ShouldRescue";s:12:"dispatchable";s:41:"Illuminate\Foundation\Events\Dispatchable";s:16:"serializesmodels";s:33:"Illuminate\Queue\SerializesModels";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:1;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:2:{i:0;s:52:"Illuminate\Contracts\Broadcasting\ShouldBroadcastNow";i:1;s:46:"Illuminate\Contracts\Broadcasting\ShouldRescue";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:3:{i:0;s:41:"Illuminate\Foundation\Events\Dispatchable";i:1;s:44:"Illuminate\Broadcasting\InteractsWithSockets";i:2;s:33:"Illuminate\Queue\SerializesModels";}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:2:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:13:"broadcastWhen";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\E