a:1:{s:53:"../../../app/Http/Middleware/EnsurePlatformAccess.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:40:"App\Http\Middleware\EnsurePlatformAccess";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:638:"/**
 * Scope + entitlement gate for authenticated platform API calls.
 *
 * Usage: `ensure.platform.access:realtime_chat.read` (dot stands for the `:`
 * in a PASETO scope — Laravel splits middleware params on `:`).
 *
 * Enforces BOTH layers from phase-3a §7:
 *  1. the token actually carries the required scope, and
 *  2. the platform holds a LIVE `platform_service_access` entitlement for the
 *     service implied by the scope (has_access = true, effective_until ≥ now).
 * The platform context is always taken from the verified token, never the body.
 * Every denial is written to the audit trail as `insufficient_scope`.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:19:"App\Http\Middleware";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:7:{s:11:"apiauditlog";s:22:"App\Models\ApiAuditLog";s:15:"apiauditservice";s:28:"App\Services\ApiAuditService";s:20:"validatedpasetotoken";s:33:"App\Services\ValidatedPasetoToken";s:7:"closure";s:7:"Closure";s:12:"jsonresponse";s:28:"Illuminate\Http\JsonResponse";s:7:"request";s:23:"Illuminate\Http\Request";s:3:"str";s:22:"Illuminate\Support\Str";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:4:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";N;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀parameters";a:1:{i:0;O:53:"PHPStan\Dependency\ExportedNode\ExportedParameterNode":8:{s:59:"␀PHPStan\Dependency\ExportedNode\