a:1:{s:52:"../../../app/Http/Middleware/ValidateWidgetToken.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:39:"App\Http\Middleware\ValidateWidgetToken";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:914:"/**
 * Authenticate a widget (browser) API request via `Authorization: Bearer`.
 *
 * Widget tokens are issued by /api/v1/widget/session (a server-to-server
 * endpoint). They are v4.local like platform tokens but carry widget-claim
 * isolation (`aud = "widget:{slug}"`, identity = token-bound user). This
 * middleware:
 *
 *   1. fully validates the widget token (signature, v4-only allow-list, exp,
 *      widget claims, revocation, mapped identity),
 *   2. sets `widget_session` (the authoritative ValidatedWidgetSession — used by
 *      ExternalUserContext so the browser can never impersonate another user), and
 *   3. ALSO sets an adapted `paseto` (ValidatedPasetoToken shaped from the widget
 *      session) so ALL downstream scope/entitlement/audit/rate-limit middleware
 *      and controllers run unchanged.
 *
 * Rejections mirror platform-token audit events (never discloses payload data).
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:19:"App\Http\Middleware";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:11:{s:12:"apiexception";s:27:"App\Exceptions\ApiException";s:11:"apiauditlog";s:22:"App\Models\ApiAuditLog";s:15:"apiauditservice";s:28:"App\Services\ApiAuditService";s:20:"validatedpasetotoken";s:33:"App\Services\ValidatedPasetoToken";s:22:"validatedwidgetsession";s:35:"App\Services\ValidatedWidgetSession";s:20:"widgetsessionservice";s:33:"App\Services\WidgetSessionService";s:15:"tokenkeycontext";s:27:"App\Support\TokenKeyContext";s:7:"closure";s:7:"Closure";s:12:"jsonresponse";s:28:"Illuminate\Http\JsonResponse";s:7:"request";s:23:"Illuminate\Http\Request";s:3:"str";s:22:"Illuminate\Support\Str";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:3:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b: