a:1:{s:44:"../../../app/Services/ChatMessageService.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:31:"App\Services\ChatMessageService";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:941:"/**
 * Message persistence (phase-3d; docs/realtime-chat.md §Delivery Flow).
 *
 * Idempotency: a send is keyed on UNIQUE(platform_id, conversation_id,
 * client_message_id). A retry of a failed/retried send converges on the ORIGINAL
 * row (never a duplicate) — including under concurrent attempts, which race onto
 * the unique index and are reconciled by one re-read.
 *
 * Side effects happen atomically with the insert in a single transaction:
 *   1. the conversation's denormalized last-message metadata, and
 *   2. unread increments for every OTHER participant (the sender's own unread
 *      never moves — read state excludes self-sent messages).
 *
 * Realtime (Phase 3E): messages are broadcast ONLY after they exist in MySQL —
 * the FIRST successful insert fires `message.created` + `conversation.updated`;
 * idempotent retries never re-broadcast. A dead transport is rescued, so realtime
 * can never fail a send.
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:12:"App\Services";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:9:{s:12:"conversation";s:23:"App\Models\Conversation";s:23:"conversationparticipant";s:34:"App\Models\ConversationParticipant";s:15:"externalusermap";s:26:"App\Models\ExternalUserMap";s:7:"message";s:18:"App\Models\Message";s:8:"platform";s:19:"App\Models\Platform";s:10:"collection";s:39:"Illuminate\Database\Eloquent\Collection";s:14:"queryexception";s:34:"Illuminate\Database\QueryException";s:2:"db";s:29:"Illuminate\Support\Facades\DB";s:3:"str";s:22:"Illuminate\Support\Str";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:3:{i:0;O:50:"PHPStan\Dependency\ExportedNode\ExportedMethodNode":11:{s:56:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀name";s:11:"__construct";s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀phpDoc";N;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀byRef";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀public";b:1;s:59:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀private";b:0;s:60:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀abstract";b:0;s:57:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀static";b:0;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode␀returnType";N;s:62:"␀PHPStan\Dependency\ExportedNode\ExportedMethodNode