a:1:{s:51:"../../../app/Services/PlatformOnboardingService.php";a:1:{i:0;O:49:"PHPStan\Dependency\ExportedNode\ExportedClassNode":10:{s:55:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀name";s:38:"App\Services\PlatformOnboardingService";s:57:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀phpDoc";O:50:"PHPStan\Dependency\ExportedNode\ExportedPhpDocNode":4:{s:64:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀phpDocString";s:853:"/**
 * Programmatic platform onboarding (Phase 3C — no dashboard UI at MVP).
 *
 * Provisions the full integration root in one idempotent call:
 *   platform (active) → integration (active, v4.local) → first primary API key
 *   → live `platform_service_access` entitlement for the requested service.
 *
 * Idempotency contract:
 *   - Re-running on a known slug reuses the existing platform + integration and
 *     only (re)confirms the entitlement.
 *   - A one-time secret is minted ONLY when no primary key exists yet. When a
 *     primary already exists the secret is null — the operator must rotate to
 *     obtain a fresh one (secrets are never re-issued or recoverable).
 *   - The raw secret is returned exactly once and then forgotten: the DB stores
 *     only the fingerprint + encrypted ciphertext (ApiKeyService contract).
 */";s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespace";s:12:"App\Services";s:56:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀uses";a:8:{s:8:"platform";s:19:"App\Models\Platform";s:14:"platformapikey";s:25:"App\Models\PlatformApiKey";s:19:"platformintegration";s:30:"App\Models\PlatformIntegration";s:21:"platformserviceaccess";s:32:"App\Models\PlatformServiceAccess";s:7:"service";s:18:"App\Models\Service";s:4:"user";s:15:"App\Models\User";s:5:"crypt";s:32:"Illuminate\Support\Facades\Crypt";s:3:"str";s:22:"Illuminate\Support\Str";}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀constUses";a:0:{}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:2:{i:0;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:18:"SYSTEM_OWNER_EMAIL";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:22:"'system@myvivah.local'";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀final";b:0;s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀phpDoc";O:50:"PHPStan\Dependency\Expo